    UnionFind uf = new UnionFind(6);
    uf.union(0, 1); uf.union(1, 2); uf.union(4, 5);
    System.out.println(uf.connected(0, 2));
    System.out.println(uf.connected(0, 5));
  }
  static class UnionFind {
    int[] parent, size;
    UnionFind(int n) { parent=new int[n]; size=new int[n]; for(int i=0;i<n;i++){parent[i]=i;size[i]=1;} }
    int find(int x) { if(parent[x]!=x) parent[x]=find(parent[x]); return parent[x]; }
    void union(int a,int b) { a=find(a); b=find(b); if(a==b)return; if(size[a]<size[b]){int t=a;a=b;b=t;} parent[b]=a; size[a]+=size[b]; }
    boolean connected(int a,int b) { return find(a)==find(b); }
  }
}

